import React, { useState } from 'react';
import {
  Card,
  ListGroup,
  Button,
  Modal,
  Toast,
  Badge,
  Container,
  Row,
  Col
} from 'react-bootstrap';
import db from '../../db';
import EditReference from './EditReference';
import { useText } from '../../../contexts/TextContext';

function ShowReferences({ references, resumeId, refreshPage }) {
  const { text: t,currentLanguage } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isEditModalOpen, setEditModalOpen] = useState(false);
  const [selectedReference, setSelectedReference] = useState(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleEditOpen = (reference) => {
    setSelectedReference(reference);
    setEditModalOpen(true);
  };

  const handleEditClose = () => {
    setEditModalOpen(false);
    setSelectedReference(null);
  };

  const handleDeleteRef = async (referenceId) => {
    if (window.confirm(t.deleteReferenceConfirmation)) {
      setIsDeleting(true);
      try {
        await db.references.delete(referenceId);
        
        setToastMessage(t.referenceDeletedSuccess);
        setToastVariant('success');
        setShowToast(true);
        
      } catch (error) {
        console.error("Error deleting reference:", error);
        setToastMessage(t.referenceDeleteError);
        setToastVariant('danger');
        setShowToast(true);
      } finally {
        setIsDeleting(false);
      }
      refreshPage();
    }
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title className="mb-4">
            {t.referencesTitle}
            <Badge bg="secondary" className="ms-2">
              {references && references.length}
            </Badge>
          </Card.Title>

          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          {references && references.length > 0 ? (
            <ListGroup variant="flush">
              {references.map(reference => (
                <ListGroup.Item key={reference.id} className="mb-3 border rounded">
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <h5 className="mb-1">
                        {reference.name} {reference.last_name}
                      </h5>
                      <small className="text-muted">
                        {reference.position} {reference.company_name && `${t.atText} ${reference.company_name}`}
                      </small>
                    </div>
                    <div>
                      <Button
                        variant="outline-primary"
                        size="sm"
                        className="me-2"
                        onClick={() => handleEditOpen(reference)}
                      >
                        {t.editButton}
                      </Button>
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleDeleteRef(reference.id)}
                        disabled={isDeleting}
                      >
                        {isDeleting ? t.deletingText : t.deleteButton}
                      </Button>
                    </div>
                  </div>

                  <div className="mt-2">
                    <Row>
                      <Col md={6}>
                        <strong>{t.emailLabel}:</strong> {reference.email}
                      </Col>
                      <Col md={6}>
                        <strong>{t.phoneLabel}:</strong> {reference.phone || t.notSpecified}
                      </Col>
                    </Row>
                  </div>

                  <div className="mt-2">
                    <strong>{t.relationshipLabel}:</strong> {reference.relation}
                  </div>
                </ListGroup.Item>
              ))}
            </ListGroup>
          ) : (
            <Card.Text className="text-muted">
              {t.noReferencesText}
            </Card.Text>
          )}

          {/* Edit Modal */}
          <Modal show={isEditModalOpen} onHide={handleEditClose} size="lg">
            <Modal.Header closeButton>
              <Modal.Title>{t.editReferenceTitle}</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              {selectedReference && (
                <EditReference 
                  reference={selectedReference} 
                  resumeId={resumeId} 
                  refreshPage={refreshPage} 
                />
              )}
            </Modal.Body>
          </Modal>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default ShowReferences;