import React, { useState, useEffect } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function EditReference({ reference, resumeId, refreshPage }) {
    const { text: t } = useText();
    const [toast, setToast] = useState({
        show: false,
        message: "",
        variant: "success",
    });

    const [formData, setFormData] = useState({
        name: "",
        last_name: "",
        email: "",
        phone: "",
        company_name: "",
        position: "",
        relation: ""
    });

    useEffect(() => {
        setFormData({
            name: reference.name || "",
            last_name: reference.last_name || "",
            email: reference.email || "",
            phone: reference.phone || "",
            company_name: reference.company_name || "",
            position: reference.position || "",
            relation: reference.relation || ""
        });
    }, [reference]);

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await db.references.updateReference(reference.id, formData);
            
            setToast({ 
                show: true, 
                message: t.referenceUpdatedSuccess, 
                variant: "success" 
            });

            refreshPage();
        } catch (error) {
            console.error('Error updating reference:', error);
            setToast({ 
                show: true, 
                message: t.referenceUpdateError, 
                variant: "danger" 
            });
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    return (
        <Container className="mt-4">
            <Row className="justify-content-center">
                <Col md={8}>
                    <Card className="shadow-sm">
                        <Card.Body>
                            <Card.Title className="mb-4">{t.editReferenceTitle}</Card.Title>
                            
                            <Toast 
                                show={toast.show} 
                                onClose={() => setToast(prev => ({ ...prev, show: false }))}
                                delay={3000} 
                                autohide
                                bg={toast.variant}
                                style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 9999 }}
                            >
                                <Toast.Body className="text-white">{toast.message}</Toast.Body>
                            </Toast>

                            <Form onSubmit={handleSubmit}>
                                <Row className="g-3">
                                    <Col md={6}>
                                        <Form.Group controlId="name">
                                            <Form.Label>{t.firstNameLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="name"
                                                value={formData.name}
                                                onChange={handleChange}
                                                placeholder={t.firstNamePlaceholder}
                                                required
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="last_name">
                                            <Form.Label>{t.lastNameLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="last_name"
                                                value={formData.last_name}
                                                onChange={handleChange}
                                                placeholder={t.lastNamePlaceholder}
                                                required
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="email">
                                            <Form.Label>{t.emailLabel}</Form.Label>
                                            <Form.Control
                                                type="email"
                                                name="email"
                                                value={formData.email}
                                                onChange={handleChange}
                                                placeholder="john.doe@example.com"
                                                required
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="phone">
                                            <Form.Label>{t.phoneLabel}</Form.Label>
                                            <Form.Control
                                                type="tel"
                                                name="phone"
                                                value={formData.phone}
                                                onChange={handleChange}
                                                placeholder="+1 (555) 123-4567"
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="company_name">
                                            <Form.Label>{t.companyNameLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="company_name"
                                                value={formData.company_name}
                                                onChange={handleChange}
                                                placeholder={t.companyNamePlaceholder}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="position">
                                            <Form.Label>{t.positionLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="position"
                                                value={formData.position}
                                                onChange={handleChange}
                                                placeholder={t.positionPlaceholder}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Form.Group controlId="relation">
                                            <Form.Label>{t.relationshipLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="relation"
                                                value={formData.relation}
                                                onChange={handleChange}
                                                placeholder={t.relationshipPlaceholder}
                                                required
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Button variant="primary" type="submit" className="w-100">
                                            {t.updateReferenceButton}
                                        </Button>
                                    </Col>
                                </Row>
                            </Form>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
}

export default EditReference;