import React, { useState } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function AddReference({ resumeId, refreshPage }) {
  const { text: t } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    name: "",
    last_name: "",
    email: "",
    phone: "",
    company_name: "",
    position: "",
    relation: ""
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Add reference using Dexie
      await db.references.addReference(resumeId, formData);
      
      setToastMessage(t.referenceAddedSuccess);
      setToastVariant('success');
      setShowToast(true);
      
      // Reset form
      setFormData({
        name: "",
        last_name: "",
        email: "",
        phone: "",
        company_name: "",
        position: "",
        relation: ""
      });

      refreshPage();
    } catch (error) {
      console.error('Error adding reference:', error);
      setToastMessage(t.referenceAddError);
      setToastVariant('danger');
      setShowToast(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title>{t.addReferenceTitle}</Card.Title>
          
          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          <Form onSubmit={handleSubmit}>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.firstNameLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder={t.firstNamePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.lastNameLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="last_name"
                    value={formData.last_name}
                    onChange={handleChange}
                    placeholder={t.lastNamePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.emailLabel}</Form.Label>
                  <Form.Control
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="john.doe@example.com"
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.phoneLabel}</Form.Label>
                  <Form.Control
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    placeholder="+1 (555) 123-4567"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.companyNameLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="company_name"
                    value={formData.company_name}
                    onChange={handleChange}
                    placeholder={t.companyNamePlaceholder}
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.positionLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="position"
                    value={formData.position}
                    onChange={handleChange}
                    placeholder={t.positionPlaceholder}
                  />
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-3">
              <Form.Label>{t.relationshipLabel}</Form.Label>
              <Form.Control
                type="text"
                name="relation"
                value={formData.relation}
                onChange={handleChange}
                placeholder={t.relationshipPlaceholder}
                required
              />
            </Form.Group>

            <div className="d-grid">
              <Button 
                variant="primary" 
                type="submit"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    {t.addingReferenceText}
                  </>
                ) : 'Add Reference'}
              </Button>
            </div>
          </Form>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default AddReference;