import React, { useState } from 'react';
import {
  Card,
  ListGroup,
  Button,
  Modal,
  Toast,
  Badge,
  Container,
  Row,
  Col
} from 'react-bootstrap';
import db from '../../db';
import EditEducation from './EditEducation';
import { useText } from '../../../contexts/TextContext';

function ShowEducations({ educations, resumeId, refreshPage }) {
  const { text: t,currentLanguage } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isEditModalOpen, setEditModalOpen] = useState(false);
  const [selectedEducation, setSelectedEducation] = useState(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleEditOpen = (education) => {
    setSelectedEducation(education);
    setEditModalOpen(true);
  };

  const handleEditClose = () => {
    setEditModalOpen(false);
    setSelectedEducation(null);
  };

  const handleDeleteEd = async (educationId) => {
    if (window.confirm(t.deleteConfirmation)) {
      setIsDeleting(true);
      try {
        await db.educations.delete(educationId);
        
        setToastMessage(t.educationDeletedSuccess);
        setToastVariant('success');
        setShowToast(true);
     
     //   refreshPage();
      } catch (error) {
        console.error("Error deleting education:", error);
        setToastMessage(t.educationDeleteError);
        setToastVariant('danger');
        setShowToast(true);
      } finally {
       
        setIsDeleting(false);
      }

      refreshPage();

    }
  };

  // const formatDate = (dateString) => {
  //   if (!dateString) return t.presentText;
  //   const options = { year: 'numeric', month: 'short' };
  //   return new Date(dateString).toLocaleDateString(undefined, options);
  // };
  const formatDate = (dateString) => {
    if (!dateString) return t.presentText;
    
    // Define language-specific month formats
    const monthFormats = {
      en: { year: 'numeric', month: 'short' },
      es: { year: 'numeric', month: 'short' },
      zh: { year: 'numeric', month: 'short' }
    };
  
    // Define locale codes for each language
    const localeCodes = {
      en: 'en-US',
      es: 'es-ES',
      zh: 'zh-CN'
    };
  
    // Get options and locale based on current language
    const options = monthFormats[currentLanguage] || monthFormats.en;
    const locale = localeCodes[currentLanguage] || localeCodes.en;
  
    return new Date(dateString).toLocaleDateString(locale, options);
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title className="mb-4">
            {t.sectionEducation}
            <Badge bg="secondary" className="ms-2">
              {educations && educations.length}
            </Badge>
          </Card.Title>

          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          {educations && educations.length > 0 ? (
            <ListGroup variant="flush">
              {educations.map(education => (
                <ListGroup.Item key={education.id} className="mb-3 border rounded">
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <h5 className="mb-1">
                        {education.degree} at {education.institution}
                      </h5>
                      <small className="text-muted">
                        {formatDate(education.initial_date)} - {formatDate(education.graduation_date)}
                      </small>
                    </div>
                    <div>
                      <Button
                        variant="outline-primary"
                        size="sm"
                        className="me-2"
                        onClick={() => handleEditOpen(education)}
                      >
                        {t.editButton}
                      </Button>
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleDeleteEd(education.id)}
                        disabled={isDeleting}
                      >
                        {isDeleting ? t.deletingText : t.deleteButton}
                      </Button>
                    </div>
                  </div>

                  {(education.country || education.place) && (
                    <div className="mt-1">
                      <strong>{t.locationLabel}:</strong> {[education.place, education.country].filter(Boolean).join(', ')}
                    </div>
                  )}

                  {education.description && (
                    <div className="mt-2">
                      <strong>{t.descriptionLabel}:</strong>
                      <p className="mb-1">{education.description}</p>
                    </div>
                  )}
                </ListGroup.Item>
              ))}
            </ListGroup>
          ) : (
            <Card.Text className="text-muted">
              {t.noEducationText}
            </Card.Text>
          )}

          {/* Edit Modal */}
          <Modal show={isEditModalOpen} onHide={handleEditClose} size="lg">
            <Modal.Header closeButton>
              <Modal.Title>{t.editEducationTitle}</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              {selectedEducation && (
                <EditEducation 
                  education={selectedEducation} 
                  resumeId={resumeId} 
                  refreshPage={refreshPage} 
                />
              )}
            </Modal.Body>
          </Modal>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default ShowEducations;