import React, { useState } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  FormCheck,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function AddExtraActivity({ resumeId, refreshPage }) {
  const { text: t } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    initial_date: '',
    end_date: '',
    job_title: '',
    company_name: '',
    place: '',
    description: '',
    current: false,
    departure_reason: ''
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Add extraactivity using Dexie
      await db.extraactivities.addExtraActivity(resumeId, formData);
      
      setToastMessage(t.extraActivityAddedSuccess);
      setToastVariant('success');
      setShowToast(true);
      
      // Reset form
      setFormData({
        initial_date: '',
        end_date: '',
        job_title: '',
        company_name: '',
        place: '',
        description: '',
        current: false,
        departure_reason: ''
      });

      refreshPage();
    } catch (error) {
      console.error('Error adding extraactivity:', error);
      setToastMessage(t.extraActivityAddError);
      setToastVariant('danger');
      setShowToast(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title>{t.addExtraActivityTitle}</Card.Title>
          
          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          <Form onSubmit={handleSubmit}>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.startDateLabel}</Form.Label>
                  <Form.Control
                    type="date"
                    name="initial_date"
                    value={formData.initial_date}
                    onChange={handleChange}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.endDateLabel}</Form.Label>
                  <Form.Control
                    type="date"
                    name="end_date"
                    value={formData.end_date}
                    onChange={handleChange}
                    disabled={formData.current}
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.jobTitleLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="job_title"
                    value={formData.job_title}
                    onChange={handleChange}
                    placeholder={t.jobTitlePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.companyNameLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="company_name"
                    value={formData.company_name}
                    onChange={handleChange}
                    placeholder={t.companyNamePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-3">
              <Form.Label>{t.locationLabel}</Form.Label>
              <Form.Control
                type="text"
                name="place"
                value={formData.place}
                onChange={handleChange}
                placeholder={t.cityPlaceholder}
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>{t.descriptionLabel}</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                name="description"
                value={formData.description}
                onChange={handleChange}
                placeholder={t.descriptionPlaceholder}
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>{t.reasonForLeavingLabel}</Form.Label>
              <Form.Control
                type="text"
                name="departure_reason"
                value={formData.departure_reason}
                onChange={handleChange}
                placeholder={t.reasonForLeavingPlaceholder}
                disabled={formData.current}
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <FormCheck
                type="checkbox"
                label={t.currentWorkCheckbox}
                name="current"
                checked={formData.current}
                onChange={handleChange}
              />
            </Form.Group>

            <div className="d-grid">
              <Button 
                variant="primary" 
                type="submit"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    {t.addingText}
                  </>
                ) : t.addExtraActivityButton}
              </Button>
            </div>
          </Form>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default AddExtraActivity;