import React, { useState, useEffect } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  FormCheck,
  Container
} from 'react-bootstrap';

import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function EditExtraActivity({ extraactivity, resumeId, refreshPage }) {
    const { text: t } = useText();
    const [toast, setToast] = useState({
        show: false,
        message: "",
        variant: "success",
    });

    const [formData, setFormData] = useState({
        initial_date: '',
        end_date: '',
        job_title: '',
        company_name: '',
        description: '',
        current: false,
        departure_reason: '',
        place: ''
    });

    useEffect(() => {
        setFormData({
            initial_date: extraactivity.initial_date || '',
            end_date: extraactivity.end_date || '',
            job_title: extraactivity.job_title || '',
            company_name: extraactivity.company_name || '',
            description: extraactivity.description || '',
            current: extraactivity.current || false,
            departure_reason: extraactivity.departure_reason || '',
            place: extraactivity.place || ''
        });
    }, [extraactivity]);

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await db.extraactivities.updateExtraActivity(extraactivity.id, formData);
            
            setToast({ 
                show: true, 
                message: t.extraActivityUpdatedSuccess, 
                variant: "success" 
            });

            refreshPage();
        } catch (error) {
            console.error('Error updating extraactivity:', error);
            setToast({ 
                show: true, 
                message: t.extraActivityUpdateError, 
                variant: "danger" 
            });
        }
    };

    return (
        <Container className="mt-4">
            <Row className="justify-content-center">
                <Col md={8}>
                    <Card className="shadow-sm">
                        <Card.Body>
                            <Card.Title className="mb-4">{t.editExtraActivityTitle}</Card.Title>
                            
                            <Toast 
                                show={toast.show} 
                                onClose={() => setToast(prev => ({ ...prev, show: false }))}
                                delay={3000} 
                                autohide
                                bg={toast.variant}
                                style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 9999 }}
                            >
                                <Toast.Body className="text-white">{toast.message}</Toast.Body>
                            </Toast>

                            <Form onSubmit={handleSubmit}>
                                <Row className="g-3">
                                    <Col md={6}>
                                        <Form.Group controlId="initial_date">
                                            <Form.Label>{t.startDateLabel}</Form.Label>
                                            <Form.Control
                                                type="date"
                                                value={formData.initial_date}
                                                onChange={e => setFormData({ ...formData, initial_date: e.target.value })}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="end_date">
                                            <Form.Label>{t.endDateLabel}</Form.Label>
                                            <Form.Control
                                                type="date"
                                                value={formData.end_date}
                                                onChange={e => setFormData({ ...formData, end_date: e.target.value })}
                                                disabled={formData.current}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="job_title">
                                            <Form.Label>{t.jobTitleLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.job_title}
                                                onChange={e => setFormData({ ...formData, job_title: e.target.value })}
                                                placeholder={t.jobTitlePlaceholder}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="company_name">
                                            <Form.Label>{t.companyNameLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.company_name}
                                                onChange={e => setFormData({ ...formData, company_name: e.target.value })}
                                                placeholder={t.companyNamePlaceholder}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Form.Group controlId="place">
                                            <Form.Label>{t.locationLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.place}
                                                onChange={e => setFormData({ ...formData, place: e.target.value })}
                                                placeholder={formData.place}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Form.Group controlId="description">
                                            <Form.Label>{t.descriptionLabel}</Form.Label>
                                            <Form.Control
                                                as="textarea"
                                                rows={3}
                                                value={formData.description}
                                                onChange={e => setFormData({ ...formData, description: e.target.value })}
                                                placeholder={t.descriptionPlaceholder}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <FormCheck
                                            type="checkbox"
                                            id="current"
                                            label={t.currentWorkCheckbox}
                                            checked={formData.current}
                                            onChange={e => setFormData({ ...formData, current: e.target.checked })}
                                        />
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Form.Group controlId="departure_reason">
                                            <Form.Label>{t.reasonForLeavingLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.departure_reason}
                                                onChange={e => setFormData({ ...formData, departure_reason: e.target.value })}
                                                placeholder={t.reasonForLeavingLabel}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Button variant="primary" type="submit" className="w-100">
                                            {t.updateExtraActivityButton}
                                        </Button>
                                    </Col>
                                </Row>
                            </Form>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
}

export default EditExtraActivity;