import React, { useState, useEffect } from 'react';
import {
    Button,
    Form,
    Card,
    Toast,
    Row,
    Col,
    FormCheck,
    Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function EditSkill({ skill, resumeId, refreshPage }) {
    const { text: t } = useText();
    const [toast, setToast] = useState({
        show: false,
        message: "",
        variant: "success",
    });

    const [formData, setFormData] = useState({
        skill_name: '',
        skill_category: '',
        skill_order: 0,
        year_amount: 0,
        proficiency: 0,
        certificate: false
    });

    useEffect(() => {
        if (skill) {
            setFormData({
                skill_name: skill.skill_name || '',
                skill_category: skill.skill_category || '',
                skill_order: skill.skill_order || 0,
                year_amount: skill.year_amount || 0,
                proficiency: skill.proficiency || 0,
                certificate: skill.certificate || false
            });
        }
    }, [skill]);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : type === 'number' ? parseInt(value) : value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await db.skills.updateSkill(skill.id, formData);

            setToast({
                show: true,
                message: t.skillUpdatedSuccess,
                variant: "success"
            });

            refreshPage();
        } catch (error) {
            console.error('Error updating skill:', error);
            setToast({
                show: true,
                message: t.skillUpdateError,
                variant: "danger"
            });
        }
    };

    return (
        <Container className="mt-4">
            <Row className="justify-content-center">
                <Col md={8}>
                    <Card className="shadow-sm">
                        <Card.Body>
                            <Card.Title className="mb-4">Edit Skill</Card.Title>

                            <Toast
                                show={toast.show}
                                onClose={() => setToast(prev => ({ ...prev, show: false }))}
                                delay={3000}
                                autohide
                                bg={toast.variant}
                                style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 9999 }}
                            >
                                <Toast.Body className="text-white">{toast.message}</Toast.Body>
                            </Toast>

                            <Form onSubmit={handleSubmit}>
                                <Row className="g-3">
                                    <Col md={6}>
                                        <Form.Group controlId="skill_name">
                                            <Form.Label>{t.skillNameLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="skill_name"
                                                value={formData.skill_name}
                                                onChange={handleChange}
                                                placeholder={t.skillNamePlaceholder}
                                                required
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col md={6}>
                                        <Form.Group controlId="skill_category">
                                            <Form.Label>{t.skillCategoryLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="skill_category"
                                                value={formData.skill_category}
                                                onChange={handleChange}
                                                placeholder={t.skillCategoryPlaceholder}
                                                required
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col md={4}>
                                        <Form.Group controlId="skill_order">
                                            <Form.Label>{t.orderLabel}</Form.Label>
                                            <Form.Control
                                                type="number"
                                                name="skill_order"
                                                value={formData.skill_order}
                                                onChange={handleChange}
                                                min="0"
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col md={4}>
                                        <Form.Group controlId="year_amount">
                                            <Form.Label>{t.yearsLabel}</Form.Label>
                                            <Form.Control
                                                type="number"
                                                name="year_amount"
                                                value={formData.year_amount}
                                                onChange={handleChange}
                                                min="0"
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col md={4}>

                                        <Form.Group className="mb-3">
                                            <Form.Label>{t.proficiencyLabel}</Form.Label>
                                            <Form.Select
                                                name="proficiency"
                                                value={formData.proficiency}
                                                onChange={handleChange}
                                                required
                                            >
                                                <option value={0}>{t.selectProficiencyPlaceholder}</option>
                                                <option value={1}>{t.beginnerProficiency}</option>
                                                <option value={2}>{t.intermediateProficiency}</option>
                                                <option value={3}>{t.expertProficiency}</option>
                                            </Form.Select>
                                        </Form.Group>

                                    </Col>

                                    <Col xs={12}>
                                        <Form.Group controlId="certificate">
                                            <FormCheck
                                                type="checkbox"
                                                label={t.certificateCheckbox}
                                                name="certificate"
                                                checked={formData.certificate}
                                                onChange={handleChange}
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col xs={12}>
                                        <Button variant="primary" type="submit" className="w-100">
                                            {t.updateSkillButton}
                                        </Button>
                                    </Col>
                                </Row>
                            </Form>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
}

export default EditSkill;