import React, { useState } from 'react';
import { Card, Container, Button, Modal, Row, Col } from 'react-bootstrap';

import ShowEducations from './ShowEducation';
import AddEducation from './AddEducation';
import { useText } from '../../../contexts/TextContext';
function EducationSection({ resumeId, educations, refreshPage }) {
  const { text: t } = useText();
  const [showModal, setShowModal] = useState(false);

  return (
    <Container className="my-4">
      {/* Show Add Button (only if no education exists) */}
      {!educations && (
        <Row className="mb-3">
          <Col>
            <Button 
              variant="primary" 
              onClick={() => setShowModal(true)}
              className="mb-3"
            >
              <i className="bi bi-plus-circle me-2"></i>
              {t.addEducationButton}
            </Button>
          </Col>
        </Row>
      )}

      {/* Display existing education entries */}
     
      {/* {JSON.stringify(educations)} */}
      <ShowEducations educations={educations} resumeId={resumeId} refreshPage={refreshPage} />

      {/* Add New Button (if education entries exist) */}
      {educations && (
        <Row>
          <Col>
            <Button 
              variant="outline-primary" 
              onClick={() => setShowModal(true)}
              size="sm"
              className="mt-2"
            >
              <i className="bi bi-plus-circle me-1"></i>
              {t.addEducationTitle}
            </Button>
          </Col>
        </Row>
      )}

      {/* Add/Edit Education Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
          {t.addEducationButton}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AddEducation 
            resumeId={resumeId} 
            refreshPage={refreshPage}
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            {t.closeButton}
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
}

export default EducationSection;