import React, { useState, useEffect } from 'react';
import {
    Button,
    Form,
    Card,
    Toast,
    Row,
    Col,
    FormCheck,
    Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';
function EditLanguage({ language, resumeId, refreshPage }) {
    const { text: t } = useText();
    const [toast, setToast] = useState({
        show: false,
        message: "",
        variant: "success",
    });

    const [formData, setFormData] = useState({
        language: "",
        proficiency: "",
        test: "",
        certificate: false
    });

    useEffect(() => {
        if (language) {
            setFormData({
                language: language.language || "",
                proficiency: language.proficiency || "",
                test: language.test || "",
                certificate: language.certificate || false
            });
        }
    }, [language]);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await db.languages.updateLanguage(language.id, formData);

            setToast({
                show: true,
                message: t.languageUpdatedSuccess,
                variant: "success"
            });

            refreshPage();
        } catch (error) {
            console.error('Error updating language:', error);
            setToast({
                show: true,
                message: t.languageUpdateError,
                variant: "danger"
            });
        }
    };

    return (
        <Container className="mt-4">
            <Row className="justify-content-center">
                <Col md={8}>
                    <Card className="shadow-sm">
                        <Card.Body>
                            <Card.Title className="mb-4">{t.editLanguageTitle}</Card.Title>

                            <Toast
                                show={toast.show}
                                onClose={() => setToast(prev => ({ ...prev, show: false }))}
                                delay={3000}
                                autohide
                                bg={toast.variant}
                                style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 9999 }}
                            >
                                <Toast.Body className="text-white">{toast.message}</Toast.Body>
                            </Toast>

                            <Form onSubmit={handleSubmit}>
                                <Row className="g-3">
                                    <Col md={6}>
                                        <Form.Group controlId="language">
                                            <Form.Label>{t.languageLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="language"
                                                value={formData.language}
                                                onChange={handleChange}
                                                placeholder={t.languagePlaceholder}
                                                required
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col md={6}>
                                        <Form.Group controlId="proficiency">
                                            <Form.Label>{t.proficiencyLabel}</Form.Label>
                                            <Form.Select
                                                name="proficiency"
                                                value={formData.proficiency}
                                                onChange={handleChange}
                                                required
                                            >
                                                <option value="">{t.selectProficiencyPlaceholder}</option>
                                                <option value="Basic">{t.basicProficiency}</option>
                                                <option value="Conversational">{t.conversationalProficiency}</option>
                                                <option value="Fluent">{t.fluentProficiency}</option>
                                                <option value="Native">{t.nativeProficiency}</option>
                                            </Form.Select>
                                        </Form.Group>
                                    </Col>

                                    <Col md={8}>
                                        <Form.Group controlId="test">
                                            <Form.Label>{t.testLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                name="test"
                                                value={formData.test}
                                                onChange={handleChange}
                                                placeholder={t.testPlaceholder}
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col md={4}>
                                        <Form.Group controlId="certificate" className="d-flex align-items-end h-100">
                                            <FormCheck
                                                type="checkbox"
                                                label={t.certificateCheckbox}
                                                name="certificate"
                                                checked={formData.certificate}
                                                onChange={handleChange}
                                            />
                                        </Form.Group>
                                    </Col>

                                    <Col xs={12}>
                                        <Button variant="primary" type="submit" className="w-100">
                                            {t.updateLanguageButton}
                                        </Button>
                                    </Col>
                                </Row>
                            </Form>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
}

export default EditLanguage;