import React from 'react';
import { Card, Container, Row, Col } from 'react-bootstrap';
import { useText } from '../../../contexts/TextContext';
function ShowHeader({ header }) {
const { text: t } = useText();

  return (
    <Container className="my-4">
      <Card className="shadow">
        <Card.Body>
          <Card.Title as="h2" className="mb-4">{t.headerInformation}</Card.Title>

          <Row className="mb-3">
            <Col sm={4}><strong>{t.nameLabel}</strong></Col>
            <Col sm={8}>{header?.name}</Col>
          </Row>

          <Row className="mb-3">
            <Col sm={4}><strong>{t.professionalTitleLabel}</strong></Col>
            <Col sm={8}>{header?.professional_title}</Col>
          </Row>

          {header?.current_company && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.currentCompanyLabel}</strong></Col>
              <Col sm={8}>{header?.current_company}</Col>
            </Row>
          )}

          {header?.current_position && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.currentPositionLabel}</strong></Col>
              <Col sm={8}>{header?.current_position}</Col>
            </Row>
          )}

          {header?.professional_summary && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.professionalSummaryLabel}</strong></Col>
              <Col sm={8}>{header?.professional_summary}</Col>
            </Row>
          )}

          {header?.phone && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.phoneLabel}</strong></Col>
              <Col sm={8}>{header?.phone}</Col>
            </Row>
          )}

          {header?.email && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.emailLabel}</strong></Col>
              <Col sm={8}>{header?.email}</Col>
            </Row>
          )}

          {header?.location && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.locationLabel}</strong></Col>
              <Col sm={8}>{header?.location}</Col>
            </Row>
          )}

          {header?.personal_site && (
            <Row className="mb-3">
              <Col sm={4}><strong>{t.personalWebsiteLabel}</strong></Col>
              <Col sm={8}>
                <a href={header?.personal_site} target="_blank" rel="noreferrer">
                  {header?.personal_site}
                </a>
              </Col>
            </Row>
          )}
        </Card.Body>
      </Card>
    </Container>
  );
}

export default ShowHeader;
