import Dexie from 'dexie';
const db = new Dexie('ResumeBuilderDB');
db.version(6).stores({  // Incremented version to 6
  resumes: '++id, title, topic',
  headers: '++id, resumeId, &[resumeId+id]',
  experiences: '++id, resumeId, [resumeId+id]',
  educations: '++id, resumeId, [resumeId+id]',
  extraactivities: '++id, resumeId, [resumeId+id]',
  skills: '++id, resumeId, [resumeId+id]',
  languages: '++id, resumeId, [resumeId+id]',
  references: '++id, resumeId, [resumeId+id]' // New references table
});

// Helper methods
db.headers.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).first();
};

db.experiences.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).toArray();
};

db.educations.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).toArray();
};

db.extraactivities.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).toArray();
};

db.skills.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).toArray();
};

db.languages.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).toArray();
};

// New helper method for references
db.references.byResume = function(resumeId) {
  return this.where('resumeId').equals(resumeId).toArray();
};

// CRUD operations for experiences
db.experiences.addExperience = async function(resumeId, experienceData) {
  return this.add({
    ...experienceData,
    resumeId,
    createdAt: new Date()
  });
};

// CRUD operations for educations
db.educations.addEducation = async function(resumeId, educationData) {
  return this.add({
    ...educationData,
    resumeId,
    createdAt: new Date()
  });
};

// CRUD operations for skills
db.skills.addSkill = async function(resumeId, skillData) {
  return this.add({
    ...skillData,
    resumeId,
    createdAt: new Date()
  });
};

// CRUD operations for languages
db.languages.addLanguage = async function(resumeId, languageData) {
  return this.add({
    ...languageData,
    resumeId,
    createdAt: new Date()
  });
};

// New CRUD operations for references
db.references.addReference = async function(resumeId, referenceData) {
  return this.add({
    ...referenceData,
    resumeId,
    createdAt: new Date()
  });
};

// Update operations
db.experiences.updateExperience = async function(id, updates) {
  return this.update(id, {
    ...updates,
    updatedAt: new Date()
  });
};

// Update operations
db.extraactivities.updateExtraActivity = async function(id, updates) {
  return this.update(id, {
    ...updates,
    updatedAt: new Date()
  });
};


db.educations.updateEducation = async function(id, updates) {
  return this.update(id, {
    ...updates,
    updatedAt: new Date()
  });
};

db.skills.updateSkill = async function(id, updates) {
  return this.update(id, {
    ...updates,
    updatedAt: new Date()
  });
};

db.languages.updateLanguage = async function(id, updates) {
  return this.update(id, {
    ...updates,
    updatedAt: new Date()
  });
};

// New update operation for references
db.references.updateReference = async function(id, updates) {
  return this.update(id, {
    ...updates,
    updatedAt: new Date()
  });
};

// Delete operations
db.extraactivities.addExtraActivity = async function(resumeId, extraactivityData) {
  return this.add({
    ...extraactivityData,
    resumeId,
    createdAt: new Date()
  });
};

// Database version upgrades
db.version(6).upgrade(trans => {
  // Create experiences table if not exists
  if (!trans.db.tables.find(t => t.name === 'experiences')) {
    trans.db.createObjectStore('experiences', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.experiences.createIndex('resumeId', 'resumeId');
  }
  
  // Create educations table if not exists
  if (!trans.db.tables.find(t => t.name === 'educations')) {
    trans.db.createObjectStore('educations', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.educations.createIndex('resumeId', 'resumeId');
  }

  // Create extraactivities table if not exists
  if (!trans.db.tables.find(t => t.name === 'extraactivities')) {
    trans.db.createObjectStore('extraactivities', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.extraactivities.createIndex('resumeId', 'resumeId');
  }

  // Create skills table if not exists
  if (!trans.db.tables.find(t => t.name === 'skills')) {
    trans.db.createObjectStore('skills', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.skills.createIndex('resumeId', 'resumeId');
  }

  // Create languages table if not exists
  if (!trans.db.tables.find(t => t.name === 'languages')) {
    trans.db.createObjectStore('languages', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.languages.createIndex('resumeId', 'resumeId');
  }

  // Create references table if not exists
  if (!trans.db.tables.find(t => t.name === 'references')) {
    trans.db.createObjectStore('references', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.references.createIndex('resumeId', 'resumeId');
  }
});

export default db;