import React, { useState } from 'react';
import {
  Card,
  ListGroup,
  Button,
  Modal,
  Toast,
  Badge,
  Container,
  Row,
  Col
} from 'react-bootstrap';
import db from '../../db';
import EditExperience from './EditExperience';
import { useText } from '../../../contexts/TextContext';
function ShowExperiences({ experiences, resumeId, refreshPage }) {
  const { text: t,currentLanguage } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isEditModalOpen, setEditModalOpen] = useState(false);
  const [selectedExperience, setSelectedExperience] = useState(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleEditOpen = (experience) => {
    setSelectedExperience(experience);
    setEditModalOpen(true);
  };

  const handleEditClose = () => {
    setEditModalOpen(false);
    setSelectedExperience(null);
  };

  const handleDeleteEx = async (experienceId) => {
    if (window.confirm(t.deleteExperienceConfirmation)) {
      setIsDeleting(true);
      try {
        // Delete experience using Dexie
        await db.experiences.delete(experienceId);
        
        setToastMessage(t.experienceDeletedSuccess);
        setToastVariant('success');
        setShowToast(true);
        
        
      } catch (error) {
        console.error("Error deleting experience:", error);
        setToastMessage(t.deleteExperienceError);
        setToastVariant('danger');
        setShowToast(true);
      } finally {
        setIsDeleting(false);
      }
      refreshPage();
    }
  };

  // const formatDate = (dateString) => {
  //   if (!dateString) return 'Present';
  //   const options = { year: 'numeric', month: 'short' };
  //   return new Date(dateString).toLocaleDateString(undefined, options);
  // };
  const formatDate = (dateString) => {
    if (!dateString) return t.presentText;
    
    // Define language-specific month formats
    const monthFormats = {
      en: { year: 'numeric', month: 'short' },
      es: { year: 'numeric', month: 'short' },
      zh: { year: 'numeric', month: 'short' }
    };
  
    // Define locale codes for each language
    const localeCodes = {
      en: 'en-US',
      es: 'es-ES',
      zh: 'zh-CN'
    };
  
    // Get options and locale based on current language
    const options = monthFormats[currentLanguage] || monthFormats.en;
    const locale = localeCodes[currentLanguage] || localeCodes.en;
  
    return new Date(dateString).toLocaleDateString(locale, options);
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title className="mb-4">
          {t.workExperienceTitle}
            <Badge bg="secondary" className="ms-2">
              {experiences && experiences.length}
            </Badge>
          </Card.Title>

          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          {experiences &&  experiences.length > 0 ? (
            <ListGroup variant="flush">
              {experiences.map(experience => (
                <ListGroup.Item key={experience.id} className="mb-3 border rounded">
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <h5 className="mb-1">
                        {experience.job_title} at {experience.company_name}
                        {experience.current && (
                          <Badge bg="success" className="ms-2">{t.presentText}</Badge>
                        )}
                      </h5>
                      <small className="text-muted">
                        {formatDate(experience.initial_date)} - {formatDate(experience.end_date)}
                      </small>
                    </div>
                    <div>
                      <Button
                        variant="outline-primary"
                        size="sm"
                        className="me-2"
                        onClick={() => handleEditOpen(experience)}
                      >
                        {t.editButton}
                      </Button>
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleDeleteEx(experience.id)}
                        disabled={isDeleting}
                      >
                        {isDeleting ? t.deletingText : t.deleteButton}
                      </Button>
                    </div>
                  </div>

                  {experience.description && (
                    <div className="mt-2">
                      <strong>{t.descriptionLabel}:</strong>
                      <p className="mb-1">{experience.description}</p>
                    </div>
                  )}

                  {experience.place && (
                    <div className="mt-1">
                      <strong>{t.locationLabel}:</strong> {experience.place}
                    </div>
                  )}

                  {experience.departure_reason && !experience.current && (
                    <div className="mt-1">
                      <strong>{t.reasonForLeavingLabel}:</strong> {experience.departure_reason}
                    </div>
                  )}
                </ListGroup.Item>
              ))}
            </ListGroup>
          ) : (
            <Card.Text className="text-muted">
              {t.noExperiencesText}
            </Card.Text>
          )}

          {/* Edit Modal */}
          <Modal show={isEditModalOpen} onHide={handleEditClose} size="lg">
            <Modal.Header closeButton>
              <Modal.Title>{t.editExperienceTitle}</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              {selectedExperience && (
                <EditExperience 
                  experience={selectedExperience} 
                  resumeId={resumeId} 
                  refreshPage={refreshPage} 
                />
              )}
            </Modal.Body>
          </Modal>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default ShowExperiences;