import React, { useState } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  FormCheck,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function AddLanguage({ resumeId, refreshPage }) {
  const { text: t } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    language: "",
    proficiency: "",
    test: "",
    certificate: false
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Add language using Dexie
      await db.languages.addLanguage(resumeId, formData);
      
      setToastMessage(t.languageAddedSuccess);
      setToastVariant('success');
      setShowToast(true);
      
      // Reset form
      setFormData({
        language: "",
        proficiency: "",
        test: "",
        certificate: false
      });

      refreshPage();
    } catch (error) {
      console.error('Error adding language:', error);
      setToastMessage(t.languageAddError);
      setToastVariant('danger');
      setShowToast(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title>{t.addLanguageTitle}</Card.Title>
          
          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          <Form onSubmit={handleSubmit}>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.languageLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="language"
                    value={formData.language}
                    onChange={handleChange}
                    placeholder={t.languagePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.proficiencyLabel}</Form.Label>
                  <Form.Select
                    name="proficiency"
                    value={formData.proficiency}
                    onChange={handleChange}
                    required
                  >
                    <option value="">{t.selectProficiencyPlaceholder}</option>
                    <option value="Basic">{t.basicProficiency}</option>
                    <option value="Conversational">{t.conversationalProficiency}</option>
                    <option value="Fluent">{t.fluentProficiency}</option>
                    <option value="Native">{t.nativeProficiency}</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={8}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.testLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="test"
                    value={formData.test}
                    onChange={handleChange}
                    placeholder={t.testPlaceholder}
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
                <Form.Group className="mb-3 d-flex align-items-end h-100">
                  <FormCheck
                    type="checkbox"
                    label={t.certificateCheckbox}
                    name="certificate"
                    checked={formData.certificate}
                    onChange={handleChange}
                  />
                </Form.Group>
              </Col>
            </Row>

            <div className="d-grid">
              <Button 
                variant="primary" 
                type="submit"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    {t.addingText}
                  </>
                ) : t.addLanguageButton}
              </Button>
            </div>
          </Form>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default AddLanguage;