import React, { useState, useEffect } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function EditEducation({ education, resumeId, refreshPage }) {
    const { text: t } = useText();
    const [toast, setToast] = useState({
        show: false,
        message: "",
        variant: "success",
    });

    const [formData, setFormData] = useState({
        initial_date: '',
        graduation_date: '',
        degree: '',
        institution: '',
        country: '',
        place: '',
        description: ''
    });

    useEffect(() => {
        setFormData({
            initial_date: education.initial_date || '',
            graduation_date: education.graduation_date || '',
            degree: education.degree || '',
            institution: education.institution || '',
            country: education.country || '',
            place: education.place || '',
            description: education.description || ''
        });
    }, [education]);

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await db.educations.updateEducation(education.id, formData);
            
            setToast({ 
                show: true, 
                message: "Education updated successfully!", 
                variant: "success" 
            });

            refreshPage();
        } catch (error) {
            console.error('Error updating education:', error);
            setToast({ 
                show: true, 
                message: "Failed to update education. Please try again.", 
                variant: "danger" 
            });
        }
    };

    return (
        <Container className="mt-4">
            <Row className="justify-content-center">
                <Col md={8}>
                    <Card className="shadow-sm">
                        <Card.Body>
                            <Card.Title className="mb-4">{t.editEducationTitle}</Card.Title>
                            
                            <Toast 
                                show={toast.show} 
                                onClose={() => setToast(prev => ({ ...prev, show: false }))}
                                delay={3000} 
                                autohide
                                bg={toast.variant}
                                style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 9999 }}
                            >
                                <Toast.Body className="text-white">{toast.message}</Toast.Body>
                            </Toast>

                            <Form onSubmit={handleSubmit}>
                                <Row className="g-3">
                                    <Col md={6}>
                                        <Form.Group controlId="initial_date">
                                            <Form.Label>{t.startDateLabel}</Form.Label>
                                            <Form.Control
                                                type="date"
                                                value={formData.initial_date}
                                                onChange={e => setFormData({ ...formData, initial_date: e.target.value })}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="graduation_date">
                                            <Form.Label>{t.graduationDateLabel}</Form.Label>
                                            <Form.Control
                                                type="date"
                                                value={formData.graduation_date}
                                                onChange={e => setFormData({ ...formData, graduation_date: e.target.value })}
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="degree">
                                            <Form.Label>{t.degreeLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.degree}
                                                onChange={e => setFormData({ ...formData, degree: e.target.value })}
                                                placeholder="Bachelor of Science"
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="institution">
                                            <Form.Label>{t.institutionLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.institution}
                                                onChange={e => setFormData({ ...formData, institution: e.target.value })}
                                                placeholder="University Name"
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="country">
                                            <Form.Label>{t.countryLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.country}
                                                onChange={e => setFormData({ ...formData, country: e.target.value })}
                                                placeholder="Country"
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col md={6}>
                                        <Form.Group controlId="place">
                                            <Form.Label>{t.cityPlaceLabel}</Form.Label>
                                            <Form.Control
                                                type="text"
                                                value={formData.place}
                                                onChange={e => setFormData({ ...formData, place: e.target.value })}
                                                placeholder="City"
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Form.Group controlId="description">
                                            <Form.Label>{t.descriptionLabel}</Form.Label>
                                            <Form.Control
                                                as="textarea"
                                                rows={3}
                                                value={formData.description}
                                                onChange={e => setFormData({ ...formData, description: e.target.value })}
                                                placeholder="Description of your studies, achievements, etc."
                                            />
                                        </Form.Group>
                                    </Col>
                                    
                                    <Col xs={12}>
                                        <Button variant="primary" type="submit" className="w-100">
                                        {t.updateEducationButton}
                                        </Button>
                                    </Col>
                                </Row>
                            </Form>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
}

export default EditEducation;