import React, { useState } from 'react';
import { Card, Container, Button, Modal, Row, Col } from 'react-bootstrap';
import ShowSkills from './ShowSkill';
import AddSkill from './AddSkill';
import { useText } from '../../../contexts/TextContext';

function SkillSection({ resumeId, skills, refreshPage }) {
  const { text: t } = useText();
  const [showModal, setShowModal] = useState(false);

  return (
    <Container className="my-4">
      {/* Show Add Button (only if no skills exist) */}
      {!skills && (
        <Row className="mb-3">
          <Col>
            <Button 
              variant="primary" 
              onClick={() => setShowModal(true)}
              className="mb-3"
            >
              <i className="bi bi-plus-circle me-2"></i>
              {t.addSkillButton}
            </Button>
          </Col>
        </Row>
      )}

      {/* Display existing skill entries */}
      <ShowSkills skills={skills} resumeId={resumeId} refreshPage={refreshPage} />

      {/* Add New Button (if skill entries exist) */}
      {skills && (
        <Row>
          <Col>
            <Button 
              variant="outline-primary" 
              onClick={() => setShowModal(true)}
              size="sm"
              className="mt-2"
            >
              <i className="bi bi-plus-circle me-1"></i>
              {t.addNewSkillButton}
            </Button>
          </Col>
        </Row>
      )}

      {/* Add Skill Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {t.addSkillButton}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AddSkill 
            resumeId={resumeId} 
            refreshPage={refreshPage}
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            {t.closeButton}
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
}

export default SkillSection;