import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Button, Card, Form, Alert, Spinner, Row, Col, Badge } from 'react-bootstrap';
import db from '../db';
import MenuSection from './MenuSection';
import HeaderSection from './header/HeaderSection';
import ExperienceSection from './experience/ExperienceSection';
import PdfPreviewer from '../PDF/PdfPreviewer';
import EducationSection from './education/EducationSection';
import ExtraActivitySection from './extraActivities/ExtraActivitySection';
import SkillSection from './skills/SkillSection';
import LanguageSection from './languages/LanguageSection';
import ReferenceSection from './reference/ReferenceSection'; // Import the new ReferenceSection
import { useText } from '../../contexts/TextContext';
class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error("Error caught by boundary:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return <div className="text-danger">Preview unavailable</div>;
    }
    return this.props.children;
  }
}

function ResumeEdit() {
  const { text: t } = useText();
  const { id } = useParams();
  const navigate = useNavigate();
  const [resume, setResume] = useState(null);
  const [header, setHeader] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [experiences, setExperiences] = useState([]);
  const [educations, setEducations] = useState([]);
  const [extraactivities, setExtraactivities] = useState([]);
  const [skills, setSkills] = useState([]);
  const [languages, setLanguages] = useState([]);
  const [references, setReferences] = useState([]); // New state for references
  const [selectedSection, setSelectedSection] = useState("header");
  const [showPDF,setShowPDF] = useState(false);

  const refreshPage = async () => {
    try {
      const [
        resumeData, 
        headerData, 
        experiencesData, 
        educationsData, 
        extraactivitiesData,
        skillsData,
        languagesData,
        referencesData // New references data
      ] = await Promise.all([
        db.resumes.get(Number(id)),
        db.headers.byResume(Number(id)+""),
        db.experiences.byResume(Number(id)+""),
        db.educations.byResume(Number(id)+""),
        db.extraactivities.byResume(Number(id)+""),
        db.skills.byResume(Number(id)+""),
        db.languages.byResume(Number(id)+""),
        db.references.byResume(Number(id)+"") // Fetch references
      ]);
      setResume(resumeData);
      setHeader(headerData);
      setExperiences(experiencesData || []);
      setEducations(educationsData || []);
      setExtraactivities(extraactivitiesData || []);
      setSkills(skillsData || []);
      setLanguages(languagesData || []);
      setReferences(referencesData || []); // Set references
    } catch (err) {
      console.error('Error refreshing data:', err);
    }
  };

  // Fetch resume and header data
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [
          resumeData, 
          headerData, 
          experiencesData, 
          educationsData, 
          extraactivitiesData,
          skillsData,
          languagesData,
          referencesData // New references data
        ] = await Promise.all([
          db.resumes.get(Number(id)),
          db.headers.byResume(Number(id)+""),
          db.experiences.byResume(Number(id)+""),
          db.educations.byResume(Number(id)+""),
          db.extraactivities.byResume(Number(id)+""),
          db.skills.byResume(Number(id)+""),
          db.languages.byResume(Number(id)+""),
          db.references.byResume(Number(id)+"") // Fetch references
        ]);
        
        if (!resumeData) {
          throw new Error('Resume not found');
        }
        
        setResume(resumeData);
        setHeader(headerData || null);
        setExperiences(experiencesData || []);
        setEducations(educationsData || []);
        setExtraactivities(extraactivitiesData || []);
        setSkills(skillsData || []);
        setLanguages(languagesData || []);
        setReferences(referencesData || []); // Set references
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  useEffect(()=>{
    console.log("changed")
  },[header,experiences,educations,skills,extraactivities,languages,references])

  const test1 = async () => {
    let datatest = await db.headers.byResume("7")
    console.log(datatest)
  }

  if (loading && !resume) {
    return (
      <div className="text-center my-5">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">{t.loadingResumes}</span>
        </Spinner>
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-4">
        {error}
        <div className="mt-2">
          <Button variant="secondary" onClick={() => navigate('/build')}>
            Back
          </Button>
        </div>
      </Alert>
    );
  }

  return (
    <>
      <Button onClick={() => navigate('/build')}>{t.back}</Button>

      <Row className="align-items-center">
        <Col md={8}>
          <h2 className="mb-3 fw-bold text-primary">
            {resume?.title || 'Untitled Resume'}
          </h2>
        </Col>
        <Col md={4} className="text-md-end">
          {resume?.topic && (
            <Badge bg="info" className="fs-6 fw-normal">
              {resume.topic}
            </Badge>
          )}
        </Col>
      </Row>

      <Row>
        <Col className='col-5'>
          <Row>
            <MenuSection 
              selectedSection={selectedSection} 
              setSelectedSection={setSelectedSection}
            />
          </Row>
         
          <Row>
            {selectedSection == "Header" && <HeaderSection resumeId={id} header={header} refreshPage={refreshPage} />}
            {selectedSection == "Experience" && <ExperienceSection resumeId={id} experiences={experiences} refreshPage={refreshPage} />}
            {selectedSection == "Education" && <EducationSection resumeId={id} educations={educations} refreshPage={refreshPage} />}
            {selectedSection == "ExtraActivities" && <ExtraActivitySection resumeId={id} extraactivities={extraactivities} refreshPage={refreshPage} />}
            {selectedSection == "Skills" && <SkillSection resumeId={id} skills={skills} refreshPage={refreshPage} />}
            {selectedSection == "Languages" && <LanguageSection resumeId={id} languages={languages} refreshPage={refreshPage} />}
            {selectedSection == "References" && <ReferenceSection resumeId={id} references={references} refreshPage={refreshPage} />}
          </Row>
        </Col>
        <Col className='col-7'>
        <Button onClick={(()=>{setShowPDF(!showPDF)})}>Show</Button>
          <ErrorBoundary>
            {showPDF && header && typeof header === 'object' && Object.keys(header).length > 0 &&
             Array.isArray(experiences) && 
             Array.isArray(educations) && 
             Array.isArray(skills) && 
             Array.isArray(extraactivities) && 
             Array.isArray(languages) && 
             Array.isArray(references) && (
              <PdfPreviewer 
                t={t}
                key={Object.keys(header).length+"_"+experiences.length+"_"+skills.length+"_"+educations.length+"_"+extraactivities.length+"_"+languages.length+"_"+references.length}
                header={header}
                experiences={experiences}
                skills={skills}
                education={educations}
                imgURL={null}
                references={references}
                extraactivities={extraactivities}
                languages={languages}
              />
            )}
          </ErrorBoundary>
        </Col>
      </Row>
    </>
  );
}

export default ResumeEdit;