import React, { useState } from 'react';
import { Card, Container, Button, Modal, Row, Col } from 'react-bootstrap';

import ShowExtraActivity from './ShowExtraActivity';
import AddExtraActivity from './AddExtraActivity';
import { useText } from '../../../contexts/TextContext';

function ExtraActivitySection({ resumeId, extraactivities, refreshPage }) {
  const { text: t } = useText();
  const [showModal, setShowModal] = useState(false);

  return (
    <Container className="my-4">
      {/* Show Header Button (only if no header exists) */}
      {!extraactivities && (
        <Row className="mb-3">
          <Col>
            <Button 
              variant="primary" 
              onClick={() => setShowModal(true)}
              className="mb-3"
            >
              <i className="bi bi-plus-circle me-2"></i>
              {t.addExtraActivityTitle}
            </Button>
          </Col>
        </Row>
      )}

      {/* Display existing header */}

      <ShowExtraActivity extraactivities={extraactivities} resumeId={resumeId} refreshPage={refreshPage}  />

      {/* Edit Button (if header exists) */}
      {extraactivities && (
        <Row>
          <Col>
            <Button 
              variant="outline-primary" 
              onClick={() => setShowModal(true)}
              size="sm"
            >
              <i className="bi bi-pencil me-1"></i>
              {t.addExtraActivityTitle}
            </Button>
          </Col>
        </Row>
      )}

      {/* Add/Edit Header Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {extraactivities ? t.editExtraActivityTitle : t.addExtraActivityTitle}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AddExtraActivity 
            resumeId={resumeId} 
            refreshPage={refreshPage} 

          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
}

export default ExtraActivitySection;