import React, { useState } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  FormCheck,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function AddSkill({ resumeId, refreshPage }) {
  const { text: t } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    skill_name: '',
    skill_category: '',
    skill_order: 0,
    year_amount: 0,
    proficiency: 0,
    certificate: false
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : type === 'number' ? parseInt(value) : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Add skill using Dexie
      await db.skills.addSkill(resumeId, formData);
      
      setToastMessage(t.skillAddedSuccess);
      setToastVariant('success');
      setShowToast(true);
      
      // Reset form
      setFormData({
        skill_name: '',
        skill_category: '',
        skill_order: 0,
        year_amount: 0,
        proficiency: 0,
        certificate: false
      });

      refreshPage();
    } catch (error) {
      console.error('Error adding skill:', error);
      setToastMessage(t.skillAddError);
      setToastVariant('danger');
      setShowToast(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title>{t.addSkillTitle}</Card.Title>
          
          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          <Form onSubmit={handleSubmit}>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.skillNameLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="skill_name"
                    value={formData.skill_name}
                    onChange={handleChange}
                    placeholder={t.skillNamePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.skillCategoryLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="skill_category"
                    value={formData.skill_category}
                    onChange={handleChange}
                    placeholder={t.skillCategoryPlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={4}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.orderLabel}</Form.Label>
                  <Form.Control
                    type="number"
                    name="skill_order"
                    value={formData.skill_order}
                    onChange={handleChange}
                    min="0"
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.yearsLabel}</Form.Label>
                  <Form.Control
                    type="number"
                    name="year_amount"
                    value={formData.year_amount}
                    onChange={handleChange}
                    min="0"
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
              <Form.Group className="mb-3">
                  <Form.Label>{t.proficiencyLabel}</Form.Label>
                  <Form.Select
                    name="proficiency"
                    value={formData.proficiency}
                    onChange={handleChange}
                    required
                  >
                    <option value={0}>{t.selectProficiencyPlaceholder}</option>
                    <option value={1}>{t.beginnerProficiency}</option>
                    <option value={2}>{t.intermediateProficiency}</option>
                    <option value={3}>{t.expertProficiency}</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-3">
              <FormCheck
                type="checkbox"
                label="Has Certificate?"
                name="certificate"
                checked={formData.certificate}
                onChange={handleChange}
              />
            </Form.Group>

            <div className="d-grid">
              <Button 
                variant="primary" 
                type="submit"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    {t.addingText}
                  </>
                ) : t.addSkillButton}
              </Button>
            </div>
          </Form>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default AddSkill;