// components/PdfPreviewer.jsx
import React from 'react';
import { PDFViewer, PDFDownloadLink } from '@react-pdf/renderer';
import MyPdfDocument from './MyPdfDocument';

const PdfPreviewer = ({t, header, experiences,skills, education, imgURL, references,extraactivities,languages }) => {
    return (
        <div>
            <h2>PDF Preview</h2>
            <PDFViewer style={{ width: '100%', height: '500px' }}>
                <MyPdfDocument  t={t}  extraactivities={extraactivities} languages={languages} references={references} imgURL={imgURL} header={header} experiences={experiences} skills={skills} education={education}/>
            </PDFViewer>
            <br />
            <PDFDownloadLink
                document={<MyPdfDocument t={t} extraactivities={extraactivities} languages={languages} references={references} header={header} experiences={experiences}  skills={skills} education={education}/>}
                fileName="resume.pdf"
            >
                <button style={{ padding: '10px', backgroundColor: 'blue', color: 'white' }}>
                    Download PDF
                </button>
            </PDFDownloadLink>
        </div>
    );
};

export default PdfPreviewer;
