import React, { useState } from 'react';
import {
    Card,
    ListGroup,
    Button,
    Modal,
    Toast,
    Badge,
    Container,
    Row,
    Col,
    ProgressBar
} from 'react-bootstrap';
import db from '../../db';
import EditSkill from './EditSkill';
import { useText } from '../../../contexts/TextContext';

function ShowSkills({ skills, resumeId, refreshPage }) {
    const { text: t,currentLanguage } = useText();
    const [showToast, setShowToast] = useState(false);
    const [toastMessage, setToastMessage] = useState('');
    const [toastVariant, setToastVariant] = useState('success');
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [selectedSkill, setSelectedSkill] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const handleEditOpen = (skill) => {
        setSelectedSkill(skill);
        setEditModalOpen(true);
    };

    const handleEditClose = () => {
        setEditModalOpen(false);
        setSelectedSkill(null);
    };

    const handleDeleteSkill = async (skillId) => {
        if (window.confirm(t.deleteSkillConfirmation)) {
            setIsDeleting(true);
            try {
                await db.skills.delete(skillId);

                setToastMessage(t.skillDeletedSuccess);
                setToastVariant('success');
                setShowToast(true);
            } catch (error) {
                console.error("Error deleting skill:", error);
                setToastMessage(t.skillDeleteError);
                setToastVariant('danger');
                setShowToast(true);
            } finally {
                setIsDeleting(false);
            }

            refreshPage();
        }
    };

    const getProficiencyVariant = (proficiency) => {
        if (proficiency >= 80) return 'success';
        if (proficiency >= 50) return 'info';
        if (proficiency >= 30) return 'warning';
        return 'danger';
    };

    // Map proficiency numbers to text labels
    // const getProficiencyLabel = (proficiency) => {
    //     switch (proficiency) {
    //         case "1": return 'Beginner';
    //         case "2": return 'Intermediate';
    //         case "3": return 'Expert';
    //         default: return 'Not Specified';
    //     }
    // };

    const getProficiencyLabel = (proficiency) => {
        return t.proficiencyLabels[proficiency] || t.proficiencyLabels.default;
      };


    return (
        <Container className="mt-4">
            <Card>
                <Card.Body>
                    <Card.Title className="mb-4">
                        {t.skillsTitle}
                        <Badge bg="secondary" className="ms-2">
                            {skills && skills.length}
                        </Badge>
                    </Card.Title>

                    {/* Toast Notification */}
                    <Toast
                        show={showToast}
                        onClose={() => setShowToast(false)}
                        delay={3000}
                        autohide
                        bg={toastVariant}
                        className="position-fixed top-0 end-0 m-3"
                    >
                        <Toast.Body className="text-white">
                            {toastMessage}
                        </Toast.Body>
                    </Toast>

                    {skills && skills.length > 0 ? (
                        <ListGroup variant="flush">
                            {skills.map(skill => (
                                <ListGroup.Item key={skill.id} className="mb-3 border rounded">
                                    <div className="d-flex justify-content-between align-items-start">
                                        <div>
                                            <h5 className="mb-1">
                                                {skill.skill_name}
                                                {skill.certificate && (
                                                    <Badge bg="success" className="ms-2">
                                                        {t.certifiedBadge}
                                                    </Badge>
                                                )}
                                            </h5>
                                            <small className="text-muted">
                                                {skill.skill_category}
                                                {skill.year_amount > 0 && (
                                                    <span> · {skill.year_amount} {
                                                        currentLanguage === 'zh' ? t.yearsExperience : 
                                                        skill.year_amount === 1 ? t.yearsExperienceSingular : t.yearsExperiencePlural
                                                      }</span>
                                                )}
                                            </small>
                                        </div>
                                        <div>
                                            <Button
                                                variant="outline-primary"
                                                size="sm"
                                                className="me-2"
                                                onClick={() => handleEditOpen(skill)}
                                            >
                                                {t.editButton}
                                            </Button>
                                            <Button
                                                variant="outline-danger"
                                                size="sm"
                                                onClick={() => handleDeleteSkill(skill.id)}
                                                disabled={isDeleting}
                                            >
                                                {isDeleting ? t.deletingText : t.deleteButton}
                                            </Button>
                                        </div>
                                    </div>

                                    <div className="mt-2">
                                        <div className="d-flex align-items-center">
                                            <span className="me-2">{t.proficiencyLabel}:</span>
                                            <Badge bg={getProficiencyVariant(skill.proficiency)}>
                                                {getProficiencyLabel(skill.proficiency)}
                                            </Badge>
                                        </div>
                                    </div>

                                    <div className="mt-1">
                                        <small className="text-muted">
                                            {t.orderLabel}: {skill.skill_order}
                                        </small>
                                    </div>
                                </ListGroup.Item>
                            ))}
                        </ListGroup>
                    ) : (
                        <Card.Text className="text-muted">
                            {t.noSkillsText}
                        </Card.Text>
                    )}

                    {/* Edit Modal */}
                    <Modal show={isEditModalOpen} onHide={handleEditClose} size="lg">
                        <Modal.Header closeButton>
                            <Modal.Title>{t.editSkillTitle}</Modal.Title>
                        </Modal.Header>
                        <Modal.Body>
                            {selectedSkill && (
                                <EditSkill
                                    skill={selectedSkill}
                                    resumeId={resumeId}
                                    refreshPage={refreshPage}
                                />
                            )}
                        </Modal.Body>
                    </Modal>
                </Card.Body>
            </Card>
        </Container>
    );
}

export default ShowSkills;